-- =====================================================================
--  Local Farm and Market Food Availability System
--  COSC444 Database Systems - Schema + sample data
--  All data is FICTIONAL (educational prototype).
--  Sample dates are relative to the day you run this script (CURDATE()),
--  so "near expiry" and "surplus" examples always work in the demo.
--  Product photos: Fruits-360 dataset (CC BY-SA 4.0), stored as BLOBs.
-- =====================================================================

DROP DATABASE IF EXISTS farm_market_db;
CREATE DATABASE farm_market_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE farm_market_db;

-- ---------------------------------------------------------------------
-- 1. Reference data (managed by administrators)
-- ---------------------------------------------------------------------
CREATE TABLE emirates (
    emirate_id   INT AUTO_INCREMENT PRIMARY KEY,
    emirate_name VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE units (
    unit_id   INT AUTO_INCREMENT PRIMARY KEY,
    unit_code VARCHAR(10) NOT NULL UNIQUE,
    unit_name VARCHAR(40) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE crops (
    crop_id         INT AUTO_INCREMENT PRIMARY KEY,
    crop_name       VARCHAR(60) NOT NULL UNIQUE,
    category        VARCHAR(30) NOT NULL DEFAULT 'Vegetable',
    default_unit_id INT NOT NULL,
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    FOREIGN KEY (default_unit_id) REFERENCES units(unit_id)
);

CREATE TABLE markets (
    market_id   INT AUTO_INCREMENT PRIMARY KEY,
    market_name VARCHAR(100) NOT NULL UNIQUE,
    emirate_id  INT NOT NULL,
    area        VARCHAR(60),
    is_active   BOOLEAN NOT NULL DEFAULT TRUE,
    FOREIGN KEY (emirate_id) REFERENCES emirates(emirate_id)
);

CREATE TABLE farms (
    farm_id    INT AUTO_INCREMENT PRIMARY KEY,
    farm_name  VARCHAR(100) NOT NULL UNIQUE,
    emirate_id INT NOT NULL,
    area       VARCHAR(60),
    is_active  BOOLEAN NOT NULL DEFAULT TRUE,
    FOREIGN KEY (emirate_id) REFERENCES emirates(emirate_id)
);

-- ---------------------------------------------------------------------
-- 2. Users and ownership
-- ---------------------------------------------------------------------
CREATE TABLE users (
    user_id   INT AUTO_INCREMENT PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    email     VARCHAR(120) NOT NULL UNIQUE,
    role      ENUM('farmer','market','admin') NOT NULL,
    market_id INT NULL,                      -- only for market buyers
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    FOREIGN KEY (market_id) REFERENCES markets(market_id),
    CONSTRAINT chk_user_market CHECK (
        (role = 'market' AND market_id IS NOT NULL) OR
        (role <> 'market' AND market_id IS NULL))
);

-- Which farmer may change which farm
CREATE TABLE farm_users (
    farm_id     INT NOT NULL,
    user_id     INT NOT NULL,
    assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (farm_id, user_id),
    FOREIGN KEY (farm_id) REFERENCES farms(farm_id),
    FOREIGN KEY (user_id) REFERENCES users(user_id)
);

-- ---------------------------------------------------------------------
-- 3. Production: crop cycles (forecast) and harvest lots (real stock)
-- ---------------------------------------------------------------------
CREATE TABLE crop_cycles (
    cycle_id              INT AUTO_INCREMENT PRIMARY KEY,
    farm_id               INT NOT NULL,
    crop_id               INT NOT NULL,
    planting_date         DATE NOT NULL,
    expected_harvest_date DATE NOT NULL,
    expected_quantity     DECIMAL(10,2) NOT NULL,   -- FORECAST only, never stock
    unit_id               INT NOT NULL,
    status                ENUM('PLANNED','GROWING','HARVESTING','COMPLETED') NOT NULL DEFAULT 'GROWING',
    created_by            INT NOT NULL,
    created_at            DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (farm_id)    REFERENCES farms(farm_id),
    FOREIGN KEY (crop_id)    REFERENCES crops(crop_id),
    FOREIGN KEY (unit_id)    REFERENCES units(unit_id),
    FOREIGN KEY (created_by) REFERENCES users(user_id),
    CONSTRAINT chk_cycle_qty   CHECK (expected_quantity >= 0),
    CONSTRAINT chk_cycle_dates CHECK (expected_harvest_date >= planting_date)
);

-- A harvest lot belongs to ONE crop cycle (its crop comes from the cycle)
CREATE TABLE harvest_lots (
    lot_id             INT AUTO_INCREMENT PRIMARY KEY,
    cycle_id           INT NOT NULL,
    quantity_harvested DECIMAL(10,2) NOT NULL,
    unit_id            INT NOT NULL,
    harvest_date       DATE NOT NULL,
    sell_by_date       DATE NULL,
    created_by         INT NOT NULL,
    created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    is_active          BOOLEAN NOT NULL DEFAULT TRUE,
    FOREIGN KEY (cycle_id)   REFERENCES crop_cycles(cycle_id),
    FOREIGN KEY (unit_id)    REFERENCES units(unit_id),
    FOREIGN KEY (created_by) REFERENCES users(user_id),
    CONSTRAINT chk_lot_qty     CHECK (quantity_harvested > 0),
    CONSTRAINT chk_lot_sell_by CHECK (sell_by_date IS NULL OR sell_by_date >= harvest_date)
);

-- Product photos stored inside MySQL (BLOB) so they survive restarts
CREATE TABLE harvest_lot_images (
    image_id    INT AUTO_INCREMENT PRIMARY KEY,
    lot_id      INT NOT NULL,
    file_name   VARCHAR(150) NOT NULL,
    mime_type   VARCHAR(20) NOT NULL,
    image_data  MEDIUMBLOB NOT NULL,
    uploaded_by INT NOT NULL,
    uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (lot_id)      REFERENCES harvest_lots(lot_id),
    FOREIGN KEY (uploaded_by) REFERENCES users(user_id),
    CONSTRAINT chk_img_type CHECK (mime_type IN ('image/jpeg','image/png'))
);

-- ---------------------------------------------------------------------
-- 4. Market requests, allocations, deliveries
-- ---------------------------------------------------------------------
CREATE TABLE market_requests (
    request_id         INT AUTO_INCREMENT PRIMARY KEY,
    market_id          INT NOT NULL,
    crop_id            INT NOT NULL,
    requested_quantity DECIMAL(10,2) NOT NULL,
    unit_id            INT NOT NULL,
    needed_by_date     DATE NOT NULL,
    status             ENUM('OPEN','PARTIALLY_ALLOCATED','FULLY_ALLOCATED',
                            'PARTIALLY_DELIVERED','DELIVERED','CANCELLED') NOT NULL DEFAULT 'OPEN',
    notes              VARCHAR(255),
    created_by         INT NOT NULL,
    created_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (market_id)  REFERENCES markets(market_id),
    FOREIGN KEY (crop_id)    REFERENCES crops(crop_id),
    FOREIGN KEY (unit_id)    REFERENCES units(unit_id),
    FOREIGN KEY (created_by) REFERENCES users(user_id),
    CONSTRAINT chk_req_qty CHECK (requested_quantity > 0)
);

-- Every request-status change keeps date, user and reason
CREATE TABLE request_status_history (
    history_id INT AUTO_INCREMENT PRIMARY KEY,
    request_id INT NOT NULL,
    old_status VARCHAR(25) NULL,
    new_status VARCHAR(25) NOT NULL,
    changed_by INT NOT NULL,
    changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reason     VARCHAR(255),
    FOREIGN KEY (request_id) REFERENCES market_requests(request_id),
    FOREIGN KEY (changed_by) REFERENCES users(user_id)
);

-- Reserves a quantity from ONE harvest lot for ONE request
CREATE TABLE allocations (
    allocation_id      INT AUTO_INCREMENT PRIMARY KEY,
    request_id         INT NOT NULL,
    lot_id             INT NOT NULL,
    allocated_quantity DECIMAL(10,2) NOT NULL,
    unit_id            INT NOT NULL,
    status             ENUM('RESERVED','DELIVERED','RELEASED') NOT NULL DEFAULT 'RESERVED',
    allocated_by       INT NOT NULL,
    allocated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (request_id)   REFERENCES market_requests(request_id),
    FOREIGN KEY (lot_id)       REFERENCES harvest_lots(lot_id),
    FOREIGN KEY (unit_id)      REFERENCES units(unit_id),
    FOREIGN KEY (allocated_by) REFERENCES users(user_id),
    CONSTRAINT chk_alloc_qty CHECK (allocated_quantity > 0)
);

-- What the market actually received (may differ from allocated)
CREATE TABLE delivery_receipts (
    receipt_id           INT AUTO_INCREMENT PRIMARY KEY,
    allocation_id        INT NOT NULL UNIQUE,
    allocated_quantity   DECIMAL(10,2) NOT NULL,
    received_quantity    DECIMAL(10,2) NOT NULL,
    discrepancy_quantity DECIMAL(10,2) NOT NULL,
    unit_id              INT NOT NULL,
    discrepancy_reason   VARCHAR(255),
    received_date        DATE NOT NULL,
    confirmed_by         INT NOT NULL,
    confirmed_at         DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (allocation_id) REFERENCES allocations(allocation_id),
    FOREIGN KEY (unit_id)       REFERENCES units(unit_id),
    FOREIGN KEY (confirmed_by)  REFERENCES users(user_id),
    CONSTRAINT chk_rcpt_nonneg CHECK (received_quantity >= 0),
    CONSTRAINT chk_rcpt_max    CHECK (received_quantity <= allocated_quantity),
    CONSTRAINT chk_rcpt_diff   CHECK (discrepancy_quantity = allocated_quantity - received_quantity)
);

-- ---------------------------------------------------------------------
-- 5. Stock movements: the ONLY source of current availability
--    on_hand  = HARVEST_ADDED + CORRECTION - DELIVERED - LOSS - DONATED - DISPOSED
--    reserved = RESERVED - RESERVATION_RELEASED - DELIVERED
--    available = on_hand - reserved
-- ---------------------------------------------------------------------
CREATE TABLE stock_movements (
    movement_id   INT AUTO_INCREMENT PRIMARY KEY,
    lot_id        INT NOT NULL,
    movement_type ENUM('HARVEST_ADDED','RESERVED','RESERVATION_RELEASED','DELIVERED',
                       'LOSS','CORRECTION','DONATED','DISPOSED') NOT NULL,
    quantity      DECIMAL(10,2) NOT NULL,   -- positive; CORRECTION may be +/-
    unit_id       INT NOT NULL,
    movement_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    user_id       INT NOT NULL,             -- responsible user
    reason        VARCHAR(255),
    allocation_id INT NULL,
    FOREIGN KEY (lot_id)        REFERENCES harvest_lots(lot_id),
    FOREIGN KEY (unit_id)       REFERENCES units(unit_id),
    FOREIGN KEY (user_id)       REFERENCES users(user_id),
    FOREIGN KEY (allocation_id) REFERENCES allocations(allocation_id),
    CONSTRAINT chk_mov_nonzero CHECK (quantity <> 0),
    CONSTRAINT chk_mov_sign    CHECK (movement_type = 'CORRECTION' OR quantity > 0)
);

CREATE INDEX idx_mov_lot   ON stock_movements(lot_id);
CREATE INDEX idx_alloc_req ON allocations(request_id);
CREATE INDEX idx_lot_cycle ON harvest_lots(cycle_id);

-- ---------------------------------------------------------------------
-- 6. Views (used by the GUI and the read-only AI assistant)
-- ---------------------------------------------------------------------
CREATE VIEW v_lot_stock AS
SELECT t.*, (t.on_hand - t.reserved) AS available
FROM (
    SELECT l.lot_id, l.cycle_id, f.farm_id, f.farm_name, e.emirate_name,
           c.crop_id, c.crop_name, u.unit_id, u.unit_code,
           l.quantity_harvested, l.harvest_date, l.sell_by_date, l.is_active,
           COALESCE(SUM(CASE m.movement_type
                WHEN 'HARVEST_ADDED' THEN m.quantity
                WHEN 'CORRECTION'    THEN m.quantity
                WHEN 'DELIVERED'     THEN -m.quantity
                WHEN 'LOSS'          THEN -m.quantity
                WHEN 'DONATED'       THEN -m.quantity
                WHEN 'DISPOSED'      THEN -m.quantity
                ELSE 0 END), 0) AS on_hand,
           COALESCE(SUM(CASE m.movement_type
                WHEN 'RESERVED'             THEN m.quantity
                WHEN 'RESERVATION_RELEASED' THEN -m.quantity
                WHEN 'DELIVERED'            THEN -m.quantity
                ELSE 0 END), 0) AS reserved
    FROM harvest_lots l
    JOIN crop_cycles cc ON cc.cycle_id = l.cycle_id
    JOIN farms f        ON f.farm_id = cc.farm_id
    JOIN emirates e     ON e.emirate_id = f.emirate_id
    JOIN crops c        ON c.crop_id = cc.crop_id
    JOIN units u        ON u.unit_id = l.unit_id
    LEFT JOIN stock_movements m ON m.lot_id = l.lot_id
    GROUP BY l.lot_id, l.cycle_id, f.farm_id, f.farm_name, e.emirate_name, c.crop_id,
             c.crop_name, u.unit_id, u.unit_code, l.quantity_harvested,
             l.harvest_date, l.sell_by_date, l.is_active
) AS t;

CREATE VIEW v_request_status AS
SELECT r.request_id, r.market_id, mk.market_name, e.emirate_name, r.crop_id, c.crop_name,
       r.requested_quantity, u.unit_code, r.needed_by_date, r.status, r.created_at,
       COALESCE((SELECT SUM(a.allocated_quantity) FROM allocations a
                 WHERE a.request_id = r.request_id AND a.status <> 'RELEASED'), 0) AS allocated_quantity,
       COALESCE((SELECT SUM(d.received_quantity) FROM delivery_receipts d
                 JOIN allocations a2 ON a2.allocation_id = d.allocation_id
                 WHERE a2.request_id = r.request_id), 0) AS received_quantity
FROM market_requests r
JOIN markets mk  ON mk.market_id = r.market_id
JOIN emirates e  ON e.emirate_id = mk.emirate_id
JOIN crops c     ON c.crop_id = r.crop_id
JOIN units u     ON u.unit_id = r.unit_id;

